/* =====================================================================
   Taller 3 - Bases de Datos II  |  Script 02: carga de datos
   ARCHIVO GENERADO por sql/generar_datos.py (semilla fija 2026).
   Ejecutar con:  sqlcmd -S .\SQLEXPRESS -E -C -f 65001 -i sql\02_carga_datos.sql
   ===================================================================== */
USE TiendaOnline;
SET NOCOUNT ON;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;  -- requerido por la columna calculada Subtotal
GO

-- Limpieza para que el script sea re-ejecutable (orden inverso a las FK)
DELETE FROM dbo.Resenas;
DELETE FROM dbo.Envios;
DELETE FROM dbo.Pagos;
DELETE FROM dbo.DetallePedido;
DELETE FROM dbo.Pedidos;
DELETE FROM dbo.Direcciones;
DELETE FROM dbo.Clientes;
DELETE FROM dbo.Productos;
DELETE FROM dbo.Proveedores;
DELETE FROM dbo.Categorias;
GO

-- Categorias: 12 registros
SET IDENTITY_INSERT dbo.Categorias ON;
SET IDENTITY_INSERT dbo.Categorias OFF;
GO

-- Proveedores: 25 registros
SET IDENTITY_INSERT dbo.Proveedores ON;
SET IDENTITY_INSERT dbo.Proveedores OFF;
GO

-- Productos: 300 registros
SET IDENTITY_INSERT dbo.Productos ON;
SET IDENTITY_INSERT dbo.Productos OFF;
GO

-- Clientes: 800 registros
SET IDENTITY_INSERT dbo.Clientes ON;
SET IDENTITY_INSERT dbo.Clientes OFF;
GO

-- Direcciones: 1185 registros
SET IDENTITY_INSERT dbo.Direcciones ON;
SET IDENTITY_INSERT dbo.Direcciones OFF;
GO

-- Pedidos: 2000 registros
SET IDENTITY_INSERT dbo.Pedidos ON;
SET IDENTITY_INSERT dbo.Pedidos OFF;
GO

-- DetallePedido: 4317 registros
SET IDENTITY_INSERT dbo.DetallePedido ON;
SET IDENTITY_INSERT dbo.DetallePedido OFF;
GO

-- Pagos: 2144 registros
SET IDENTITY_INSERT dbo.Pagos ON;
SET IDENTITY_INSERT dbo.Pagos OFF;
GO

-- Envios: 1866 registros
SET IDENTITY_INSERT dbo.Envios ON;
SET IDENTITY_INSERT dbo.Envios OFF;
GO

-- Resenas: 1378 registros
SET IDENTITY_INSERT dbo.Resenas ON;
SET IDENTITY_INSERT dbo.Resenas OFF;
GO

PRINT 'Carga completa: 14027 registros en 10 tablas.';
